var RR_TYPES = ['A','AAAA','CNAME','MX','TXT','NS','SRV','CAA','PTR','SOA'];
function isIPv4(s){
  if(typeof s!=='string') return false;
  var p=s.split('.');
  if(p.length!==4) return false;
  for(var i=0;i<4;i++){
    if(!/^\d{1,3}$/.test(p[i])) return false;
    var v=parseInt(p[i],10);
    if(v<0 || v>255) return false;
    if(p[i].length>1 && p[i].charAt(0)==='0') return false;
  }
  return true;
}
function isIPv6(s){
  if(typeof s!=='string' || s.indexOf(':')<0) return false;
  if((s.match(/::/g)||[]).length>1) return false;
  var parts=s.split(':');
  if(parts.length>8) return false;
  for(var i=0;i<parts.length;i++){
    if(parts[i]==='') continue;
    if(!/^[0-9a-fA-F]{1,4}$/.test(parts[i])) return false;
  }
  return true;
}
function isHostname(s){
  if(typeof s!=='string' || !s.length || s.length>253) return false;
  var t=s.replace(/\.$/,'');
  if(!t.length) return false;
  var labels=t.split('.');
  for(var i=0;i<labels.length;i++){
    var l=labels[i];
    if(!l.length || l.length>63) return false;
    if(!/^[a-zA-Z0-9_]([a-zA-Z0-9_-]*[a-zA-Z0-9_])?$/.test(l)) return false;
  }
  return true;
}
function parseTtl(s){
  if(typeof s==='number') return Math.floor(s);
  var t=String(s||'').trim();
  if(/^\d+$/.test(t)) return parseInt(t,10);
  var m=t.match(/^(\d+)([smhdw])$/i);
  if(!m) return null;
  var mult={s:1,m:60,h:3600,d:86400,w:604800}[m[2].toLowerCase()];
  return parseInt(m[1],10)*mult;
}
function formatTtl(sec){
  sec=Math.max(0,Math.floor(sec||0));
  if(sec>=604800 && sec%604800===0) return (sec/604800)+'w';
  if(sec>=86400 && sec%86400===0) return (sec/86400)+'d';
  if(sec>=3600 && sec%3600===0) return (sec/3600)+'h';
  if(sec>=60 && sec%60===0) return (sec/60)+'m';
  return sec+'s';
}
function parseRecord(line){
  var t=String(line||'').trim();
  if(!t || t.charAt(0)===';' || t.charAt(0)==='#') return null;
  var f=t.split(/\s+/);
  if(f.length<3) return {raw:t, error:'字段不足，至少需要 name / type / value'};
  var name=f[0], idx=1, ttl=null, cls=null;
  var maybeTtl=parseTtl(f[idx]);
  if(maybeTtl!==null){ ttl=maybeTtl; idx++; }
  if(f[idx] && /^(IN|CH|HS)$/i.test(f[idx])){ cls=f[idx].toUpperCase(); idx++; }
  if(ttl===null && f[idx]){ var t2=parseTtl(f[idx]); if(t2!==null){ ttl=t2; idx++; } }
  var type=(f[idx]||'').toUpperCase(); idx++;
  var value=f.slice(idx).join(' ');
  if(RR_TYPES.indexOf(type)<0) return {raw:t, name:name, type:type, error:'不支持或未知的记录类型：'+type};
  return {raw:t, name:name, ttl:ttl, 'class':cls||'IN', type:type, value:value};
}
function validateRecord(r){
  if(!r) return {valid:false, errors:['空记录'], warnings:[]};
  if(r.error) return {valid:false, errors:[r.error], warnings:[]};
  var errs=[], warns=[], v=r.value;
  if(r.ttl===null || r.ttl===undefined) warns.push('未设置 TTL，将继承 $TTL 默认值');
  else {
    if(r.ttl<30) warns.push('TTL 过短（'+r.ttl+'s），解析压力大且部分递归服务器会强制抬高');
    if(r.ttl>604800) warns.push('TTL 超过 7 天，故障切换会非常缓慢');
  }
  if(r.type==='A'){ if(!isIPv4(v)) errs.push('A 记录的值必须是合法 IPv4'); }
  else if(r.type==='AAAA'){ if(!isIPv6(v)) errs.push('AAAA 记录的值必须是合法 IPv6'); }
  else if(r.type==='CNAME'){
    if(!isHostname(v)) errs.push('CNAME 的值必须是合法主机名');
    if(r.name==='@') errs.push('根域（@）不能设置 CNAME，请改用 ALIAS/ANAME');
  }
  else if(r.type==='MX'){
    var mp=v.split(/\s+/);
    if(mp.length<2) errs.push('MX 记录需要「优先级 主机名」两个字段');
    else {
      if(!/^\d+$/.test(mp[0])) errs.push('MX 优先级必须是整数');
      else if(parseInt(mp[0],10)>65535) errs.push('MX 优先级不能超过 65535');
      if(!isHostname(mp[1])) errs.push('MX 目标必须是合法主机名');
      if(isIPv4(mp[1])) errs.push('MX 目标不能是 IP 地址，必须是主机名');
    }
  }
  else if(r.type==='TXT'){
    var inner=v.replace(/^"|"$/g,'');
    if(inner.length>255) warns.push('单条 TXT 超过 255 字节，需要拆分为多个字符串');
    if(!/^".*"$/.test(v) && /\s/.test(v)) warns.push('含空格的 TXT 建议用双引号包裹');
  }
  else if(r.type==='NS'){ if(!isHostname(v)) errs.push('NS 的值必须是合法主机名'); }
  else if(r.type==='SRV'){
    var sp=v.split(/\s+/);
    if(sp.length<4) errs.push('SRV 需要「优先级 权重 端口 目标」四个字段');
    else {
      if(!/^\d+$/.test(sp[2]) || parseInt(sp[2],10)>65535) errs.push('SRV 端口非法');
      if(!isHostname(sp[3]) && sp[3]!=='.') errs.push('SRV 目标必须是主机名或 .');
    }
    if(!/^_/.test(r.name)) warns.push('SRV 名称通常形如 _service._proto.name');
  }
  else if(r.type==='CAA'){
    var cp=v.split(/\s+/);
    if(cp.length<3) errs.push('CAA 需要「flags tag value」三个字段');
    else if(['issue','issuewild','iodef'].indexOf(cp[1].replace(/"/g,''))<0)
      warns.push('CAA tag 通常为 issue / issuewild / iodef');
  }
  return {valid: errs.length===0, errors:errs, warnings:warns};
}
function parseZone(text){
  var lines=String(text||'').split(/\r?\n/), out=[];
  for(var i=0;i<lines.length;i++){
    var r=parseRecord(lines[i]);
    if(!r) continue;
    var v=validateRecord(r);
    out.push({line:i+1, record:r, valid:v.valid, errors:v.errors, warnings:v.warnings});
  }
  return out;
}
function zoneSummary(rows){
  var byType={}, errors=0, warnings=0, cnameNames={}, conflicts=[];
  for(var i=0;i<rows.length;i++){
    var r=rows[i];
    var t=(r.record && r.record.type) || '?';
    byType[t]=(byType[t]||0)+1;
    errors+=r.errors.length; warnings+=r.warnings.length;
    if(t==='CNAME' && r.record.name) cnameNames[r.record.name]=1;
  }
  for(var j=0;j<rows.length;j++){
    var rr=rows[j];
    if(!rr.record || rr.record.type==='CNAME') continue;
    if(cnameNames[rr.record.name]) conflicts.push(rr.record.name+' 同时存在 CNAME 与 '+rr.record.type+' 记录');
  }
  return {total:rows.length, byType:byType, errors:errors, warnings:warnings, conflicts:conflicts};
}
function propagationEstimate(ttlSec){
  var t=Math.max(0, Math.floor(ttlSec||0));
  return {typical:t, worstCase:t*2, humanTypical:formatTtl(t), humanWorst:formatTtl(t*2)};
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { isIPv4:isIPv4, isIPv6:isIPv6, isHostname:isHostname, parseTtl:parseTtl, formatTtl:formatTtl, parseRecord:parseRecord, validateRecord:validateRecord, parseZone:parseZone, zoneSummary:zoneSummary, propagationEstimate:propagationEstimate, RR_TYPES:RR_TYPES }; }
if (typeof window !== 'undefined') { window.DnsForgePure = { isIPv4:isIPv4, isIPv6:isIPv6, isHostname:isHostname, parseTtl:parseTtl, formatTtl:formatTtl, parseRecord:parseRecord, validateRecord:validateRecord, parseZone:parseZone, zoneSummary:zoneSummary, propagationEstimate:propagationEstimate, RR_TYPES:RR_TYPES }; }
